// Database type definitions — will be auto-generated by Supabase CLI later.
// For now, we define them manually so the app compiles.

export type UserRole = 'candidate' | 'recruiter' | 'admin'
export type WorkMode = 'remote' | 'hybrid' | 'onsite'
export type JobStatus = 'draft' | 'active' | 'closed'
export type ApplicationStatus = 'applied' | 'shortlisted' | 'rejected' | 'hired'
export type Importance = 'must' | 'nice'

export interface Profile {
  id: string
  role: UserRole
  full_name: string | null
  headline: string | null
  location: string | null
  years_experience: number | null
  created_at: string
}

export interface Skill {
  id: string
  name: string
  category: string
  aliases: string[]
}

export interface SkillRelation {
  skill_id: string
  related_skill_id: string
  similarity: number
}

export interface CandidateSkill {
  candidate_id: string
  skill_id: string
  proficiency: number // 1-5
  years: number | null
  skill?: Skill
}

export interface Job {
  id: string
  recruiter_id: string
  title: string
  company: string
  description: string | null
  location: string | null
  work_mode: WorkMode
  salary_min: number | null
  salary_max: number | null
  status: JobStatus
  created_at: string
}

export interface JobSkill {
  job_id: string
  skill_id: string
  required_level: number // 1-5
  importance: Importance
  weight: number
  skill?: Skill
}

export interface Application {
  id: string
  job_id: string
  candidate_id: string
  status: ApplicationStatus
  match_score: number | null
  created_at: string
  job?: Job
  profile?: Profile
}

export interface SavedJob {
  candidate_id: string
  job_id: string
  job?: Job
}

// RPC return types
export interface JobMatchResult {
  job_id: string
  title: string
  company: string
  location: string | null
  work_mode: WorkMode
  salary_min: number | null
  salary_max: number | null
  status: JobStatus
  score: number
  matched_skills: MatchedSkillDetail[]
  partial_skills: PartialSkillDetail[]
  missing_skills: MissingSkillDetail[]
}

export interface CandidateMatchResult {
  candidate_id: string
  full_name: string | null
  headline: string | null
  location: string | null
  years_experience: number | null
  score: number
  matched_skills: MatchedSkillDetail[]
  partial_skills: PartialSkillDetail[]
  missing_skills: MissingSkillDetail[]
}

export interface MatchedSkillDetail {
  skill_id: string
  skill_name: string
  candidate_level: number
  required_level: number
  credit: number
}

export interface PartialSkillDetail {
  skill_id: string
  skill_name: string
  via_skill_id: string
  via_skill_name: string
  similarity: number
  credit: number
}

export interface MissingSkillDetail {
  skill_id: string
  skill_name: string
  importance: Importance
  required_level: number
}

// Supabase Database type (for typed client)
export type Database = {
  public: {
    Tables: {
      profiles: {
        Row: Profile
        Insert: Partial<Profile> & { id: string; role: UserRole }
        Update: Partial<Profile>
      }
      skills: {
        Row: Skill
        Insert: Omit<Skill, 'id'>
        Update: Partial<Omit<Skill, 'id'>>
      }
      skill_relations: {
        Row: SkillRelation
        Insert: SkillRelation
        Update: Partial<SkillRelation>
      }
      candidate_skills: {
        Row: CandidateSkill
        Insert: CandidateSkill
        Update: Partial<CandidateSkill>
      }
      jobs: {
        Row: Job
        Insert: Omit<Job, 'id' | 'created_at'>
        Update: Partial<Omit<Job, 'id' | 'created_at'>>
      }
      job_skills: {
        Row: JobSkill
        Insert: JobSkill
        Update: Partial<JobSkill>
      }
      applications: {
        Row: Application
        Insert: Omit<Application, 'id' | 'created_at'>
        Update: Partial<Omit<Application, 'id' | 'created_at'>>
      }
      saved_jobs: {
        Row: SavedJob
        Insert: SavedJob
        Update: never
      }
    }
    Functions: {
      match_jobs_for_candidate: {
        Args: { p_candidate_id: string }
        Returns: JobMatchResult[]
      }
      match_candidates_for_job: {
        Args: { p_job_id: string }
        Returns: CandidateMatchResult[]
      }
    }
  }
}
